<span class="line"><span style="color:#24292E;">    &lt;</span><span style="color:#005CC5;">Route</span><span style="color:#6F42C1;"> path</span><span style="color:#D73A49;">=</span><span style="color:#032F62;">&quot;/&quot;</span><span style="color:#6F42C1;"> component</span><span style="color:#D73A49;">=</span><span style="color:#24292E;">{Index}&gt;</span></span>
